// Expected snaps by situation (G7.2.3). Expected snaps for a box = the share of the reference table's
// offensive run and pass snaps (kneels, spikes and tries excluded) that match the box's rule, times the
// table's mean snaps per team game. The team's own table replaces the league's once it has enough games.
//
// The pro starting table is the 2024 NFL regular season from the nflverse play-by-play release
// (https://github.com/nflverse/nflverse-data/releases/tag/pbp), generated by test/gameplan/build_reference.py.
// Status: 1 of 3 (one data set). This module re-ran the computation on 2026-11-26 and reproduced every
// G7.2.3 figure (61.3 snaps, first down 26.9, second 20.4, third 12.6 split 3.6/3.2/3.4/2.4, fourth 1.4,
// red zone 9.5 split 4.9/3.0/1.6, fringe 12.1, backed up 1.6, last two minutes 7.3, no-huddle 7.5, drives
// 10.8), which checks the bible writer's arithmetic but is the same data set, so the status stays
// PROVISIONAL until a second source is read (G7.2.3 open question, register owner Q6). In a career the table
// is rebuilt from the simulated league's own records (`tableFromStates`), so it drifts with that league.
// The college starting table is the 2024 FBS regular season (both teams FBS) from the cfbfastR play-by-play
// release (https://github.com/sportsdataverse/sportsdataverse-data/releases/tag/cfbfastR_cfb_pbp), generated
// by test/gameplan/build_reference_college.py: 752 games, 98,609 run and pass snaps, 65.6 a team game with
// kneels and spikes left out. Status: 1 of 3 (fact F-measured-rate-0390). Publishers that count plays (ESPN box
// scores, NCAA.com) include kneel-downs and land 0.5 to 1 play a game higher, as fact F-measured-rate-0282
// records, so they do not confirm the figure on the same definition. The release has no no-huddle flag, so
// tempo is an unseen field of the college table and a tempo box gets an approximate (upper bound) figure.
import { param } from './params.ts';
import { COLLEGE_2024_CELLS, COLLEGE_2024_DRIVES, COLLEGE_2024_TEAM_GAMES } from './reference-college-2024.ts';
import { PRO_2024_CELLS, PRO_2024_DRIVES, PRO_2024_TEAM_GAMES } from './reference-pro-2024.ts';
import { fieldsOf, situationMatches, NEUTRAL_STATE, type ConditionField, type SituationRule, type SituationState } from './situations.ts';

export interface RefCell { readonly state: SituationState; readonly n: number }
export interface ReferenceTable {
  readonly id: string;
  readonly source: 'league' | 'team';
  /** Team games the table covers (shown with every figure, G7.2.3 acceptance). */
  readonly games: number;
  readonly cells: readonly RefCell[];
  /** Fields the table's states do not record: a condition on one is skipped and the figure marked approximate. */
  readonly unseen: ReadonlySet<ConditionField>;
  readonly drivesPerGame: number | null;
  readonly status: string;
}

const HALF_BUCKET_EDGE = [120, 240, 480, 1800] as const;

function decode(enc: string): RefCell[] {
  return enc.split(';').map((c) => {
    const down = parseInt(c[0]!, 36);
    const dist = parseInt(c[1]!, 36);
    const ytg = parseInt(c.slice(2, 4), 36);
    const hb = parseInt(c[4]!, 10);
    const half = parseInt(c[5]!, 10);
    const noHuddle = c[6] === '1';
    const n = parseInt(c.slice(7), 36);
    const halfSecondsLeft = HALF_BUCKET_EDGE[hb]!;
    const state: SituationState = {
      ...NEUTRAL_STATE, down, distanceYd: dist, yardsToGoalYd: ytg, halfSecondsLeft,
      gameSecondsLeft: half === 1 ? halfSecondsLeft + 1800 : half === 2 ? halfSecondsLeft : 0,
      tempo: noHuddle ? 'no_huddle' : 'huddle',
    };
    return { state, n };
  });
}

let proCache: ReferenceTable | null = null;
/** The pro league reference table (2024 NFL regular season, PROVISIONAL 1 of 3). */
export function proReference2024(): ReferenceTable {
  proCache ??= {
    id: 'nflverse-pbp-2024-reg',
    source: 'league',
    games: PRO_2024_TEAM_GAMES,
    cells: decode(PRO_2024_CELLS),
    unseen: new Set<ConditionField>(['scoreDiff', 'timeouts', 'personnel', 'formationFamily', 'hash', 'afterEvent']),
    drivesPerGame: PRO_2024_DRIVES / PRO_2024_TEAM_GAMES,
    status: 'PROVISIONAL (1 of 3: nflverse 2024 play-by-play, recomputed 2026-11-26)',
  };
  return proCache;
}

let collegeCache: ReferenceTable | null = null;
/** The college league reference table (2024 FBS regular season, FBS against FBS, PROVISIONAL 1 of 3). */
export function collegeReference2024(): ReferenceTable {
  collegeCache ??= {
    id: 'cfbfastr-pbp-2024-fbs-reg',
    source: 'league',
    games: COLLEGE_2024_TEAM_GAMES,
    cells: decode(COLLEGE_2024_CELLS),
    unseen: new Set<ConditionField>(['scoreDiff', 'timeouts', 'personnel', 'formationFamily', 'hash', 'afterEvent', 'tempo']),
    drivesPerGame: COLLEGE_2024_DRIVES / COLLEGE_2024_TEAM_GAMES,
    status: 'PROVISIONAL (1 of 3: cfbfastR 2024 FBS play-by-play, F-measured-rate-0390)',
  };
  return collegeCache;
}

export type ReferenceLevel = 'pro' | 'college';
const LEAGUE_TABLES: Readonly<Record<ReferenceLevel, () => ReferenceTable>> = { pro: proReference2024, college: collegeReference2024 };
/** The league starting table for a level (G7.2.3); a career replaces it with the simulated league's own. */
export function leagueReference(level: ReferenceLevel): ReferenceTable {
  return LEAGUE_TABLES[level]();
}

/** A table from recorded states (the team's own call records, or the simulated league's). Kneels, spikes and tries must already be left out. */
export function tableFromStates(id: string, source: 'league' | 'team', states: readonly SituationState[], games: number, drives: number | null = null): ReferenceTable {
  const cells = states.filter((s) => s.kind === 'scrimmage').map((state) => ({ state, n: 1 }));
  return { id, source, games, cells, unseen: new Set(), drivesPerGame: drives === null || games === 0 ? null : drives / games, status: 'computed from records' };
}

/** G7.2.3: the team's own figure once it has the minimum games, otherwise the league's. */
export function chooseTable(team: ReferenceTable | null, league: ReferenceTable | null): ReferenceTable | null {
  if (team && team.games >= param('snaps.teamMinGames')) return team;
  return league;
}

export function snapsPerGame(t: ReferenceTable): number {
  return t.games === 0 ? 0 : t.cells.reduce((a, c) => a + c.n, 0) / t.games;
}

export interface ExpectedSnaps {
  readonly value: number;
  readonly source: 'league' | 'team';
  readonly games: number;
  readonly tableId: string;
  /** Conditions the table cannot see were skipped (the figure is an upper bound). */
  readonly approximate: boolean;
  readonly skipped: readonly ConditionField[];
}

/** Expected snaps per team game for a situation. */
export function expectedSnaps(sit: SituationRule, t: ReferenceTable): ExpectedSnaps {
  const skipped = [...fieldsOf(sit)].filter((f) => t.unseen.has(f));
  const hits = t.cells.reduce((a, c) => a + (situationMatches(sit, c.state, t.unseen) ? c.n : 0), 0);
  return { value: t.games === 0 ? 0 : hits / t.games, source: t.source, games: t.games, tableId: t.id, approximate: skipped.length > 0, skipped };
}

export type DepthMark = 'deep' | 'thin' | null;
/** G7.2.3 depth marks: deep above 3 x expected + 2 entries, thin below expected rounded down. Information only. */
export function depthMark(entries: number, expected: number): DepthMark {
  if (entries > param('snaps.deepFactor') * expected + param('snaps.deepPlus')) return 'deep';
  if (entries < Math.floor(expected)) return 'thin';
  return null;
}
